```
let rngState = (seed>>>0)||0x9e3779b9;
function rnd(){ rngState|=0; rngState=(rngState+0x6D2B79F5)|0; let t=Math.imul(rngState^(rngState>>>15),1|rngState); t=(t+Math.imul(t^(t>>>7),61|t))^t; return ((t^(t>>>14))>>>0)/4294967296; }
