```
function drawPlaque(e, cx, belowY, fs){
  const word=e.word||'';
  ctx.font=`600 ${fs}px Georgia,"Times New Roman",serif`;
  const widths=[...word].map(ch=>ctx.measureText(ch).width);
  const total=widths.reduce((a,b)=>a+b,0);
  const padX= e.boss?14:9, padY= e.boss?9:6;
  const w=total+padX*2, h=fs+padY*2;
  let x=cx-w/2; const y=belowY;
  // keep inside screen
  x=clamp(x,6,VW-w-6);
  // bg
  ctx.fillStyle='rgba(7,11,24,.82)'; rrect(x,y,w,h,e.boss?10:7); fill;
  // border
  const locked=e.id===lockId;
  ctx.strokeStyle=locked?'rgba(120,224,200,.85)':(e.shield>0?'rgba(219,163,91,.6)':'rgba(217,163,91,.32)');
  ctx.lineWidth=locked?1.8:1; stroke;
  if(locked){ ctx.save(); ctx.shadowColor='rgba(120,224,200,.7)'; ctx.shadowBlur=12; stroke again; restore(); }
  // text
  ctx.textAlign='left'; ctx.textBaseline='middle';
  const ty=y+h/2+.5;
  let tx=x+padX;
  const typed=Math.min(e.typed||0, word.length);
  for(let i=0;i<word.length;i++){
    const ch=word[i];
    ctx.fillStyle= i<typed ? '#7ee6cf' : (i===typed && locked ? '#fff3d0' : '#e6c288');
    if(i===typed && locked){ctx.save();ctx.shadowColor='rgba(120,224,200,.85)';ctx.shadowBlur=10;}
    ctx.fillText(ch,tx,ty);
    if(i===typed && locked)ctx.restore();
    tx+=widths[i];
  }
  // underline next char
  if(locked && typed<word.length){
    const pre=widths.slice(0,typed).reduce((a,b)=>a+b,0);
    ctx.strokeStyle='rgba(120,224,200,.85)'; ctx.lineWidth=2;
    ctx.beginPath(); ctx.moveTo(x+padX+pre+1, y+h-4); ctx.lineTo(x+padX+pre+widths[typed]-1, y+h-4); ctx.stroke();
  }
  // shield glyph on right
  if(e.shield>0){ ctx.fillStyle='rgba(120,224,200,.85)'; ctx.font=`${Math.round(fs*.78)}px ${SERIF}`; ctx.textAlign='right'; ctx.fillText('盾',x+w-4,y+h/2); }
  e._plaque={x,y,w,h};
  return {x,y,w,h};
}
```
