  waveActive = false;
  const w = wave;
  const sBonus = 12 * w, iBonus = 8 + 2 * w;
  score += sBonus; ink += iBonus;
  saveRecords();
  report('progress', { score: Math.round(score), progress: w, wave: w });
  audio.setState('calm'); audio.sfx.wave();
  showBanner(`第 ${w} 波 · 已 清`, `+${sBonus} 分 · +${iBonus} 墨能`, 1500);
  showToast(`墨能 +${iBonus}`);
