    ctx.globalAlpha = clamp(f.life / f.max, 0, 1);
    ctx.font = `700 ${f.size}px ${SERIF}`;
    ctx.strokeStyle = 'rgba(4,7,15,.8)'; ctx.lineWidth = 3;
