      ctx.fillStyle = 'rgba(255,232,190,.13)'; rrect(ctx, x - w / 2 + 5, y - h / 2 + 4, w - 10, 7, 3); ctx.fill();
      ctx.fillStyle = 'rgba(255,232,190,.65)';
