      ctx.strokeStyle = 'rgba(255,232,190,.22)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(x, y - h / 2 + 3); ctx.lineTo(x, y + h / 2 - 3); ctx.stroke();
      ctx.strokeStyle = 'rgba(240,138,95,.28)'; ctx.lineWidth = 1.4;
